using Microsoft.Data.SqlClient;
using SmaComplaints.Models;
namespace SmaComplaints.Data;
public sealed class SqlNotificationStore(IConfiguration configuration):INotificationStore
{
 SqlConnection Connection()=>new(configuration.GetConnectionString("Complaints"));
 static AppNotification Read(SqlDataReader r)=>new(){Id=r.GetGuid(0),RecipientId=r.GetGuid(1),EventKey=r.GetString(2),Title=r.GetString(3),Body=r.GetString(4),Url=r.GetString(5),At=r.GetFieldValue<DateTimeOffset>(6),ReadAt=r.IsDBNull(7)?null:r.GetFieldValue<DateTimeOffset>(7)};
 public async Task<NotificationFeed> FeedAsync(Guid userId){var through=DateTimeOffset.UtcNow;await using var db=Connection();await db.OpenAsync();await using var c=db.CreateCommand();c.CommandText="SELECT COUNT(*) FROM dbo.AppNotifications WHERE RecipientId=@User AND ReadAt IS NULL;SELECT TOP(50) Id,RecipientId,EventKey,Title,Body,Url,At,ReadAt FROM dbo.AppNotifications WHERE RecipientId=@User ORDER BY CASE WHEN ReadAt IS NULL THEN 0 ELSE 1 END,At DESC";c.Parameters.AddWithValue("@User",userId);try{await using var r=await c.ExecuteReaderAsync();await r.ReadAsync();var count=r.GetInt32(0);await r.NextResultAsync();var items=new List<AppNotification>();while(await r.ReadAsync())items.Add(Read(r));return new(count,items){Through=through};}catch(SqlException ex)when(ex.Number==208){throw new WorkflowException("Notifications need the 003_notifications.sql database migration.");}}
 public async Task<AppNotification?> FindAsync(Guid userId,Guid id){await using var db=Connection();await db.OpenAsync();await using var c=db.CreateCommand();c.CommandText="SELECT Id,RecipientId,EventKey,Title,Body,Url,At,ReadAt FROM dbo.AppNotifications WHERE Id=@Id AND RecipientId=@User";c.Parameters.AddWithValue("@Id",id);c.Parameters.AddWithValue("@User",userId);await using var r=await c.ExecuteReaderAsync();return await r.ReadAsync()?Read(r):null;}
 public async Task ReadAsync(Guid userId,Guid? id,DateTimeOffset through){await using var db=Connection();await db.OpenAsync();await using var c=db.CreateCommand();c.CommandText="UPDATE dbo.AppNotifications SET ReadAt=SYSUTCDATETIME() WHERE RecipientId=@User AND ReadAt IS NULL AND At<=@Through AND (@Id IS NULL OR Id=@Id)";c.Parameters.AddWithValue("@User",userId);c.Parameters.Add("@Id",System.Data.SqlDbType.UniqueIdentifier).Value=(object?)id??DBNull.Value;c.Parameters.AddWithValue("@Through",through);await c.ExecuteNonQueryAsync();}
 public static async Task InsertAsync(SqlConnection db,SqlTransaction tx,IEnumerable<NotificationDelivery> deliveries)
 {
  foreach(var d in deliveries){await using var c=db.CreateCommand();c.Transaction=tx;c.CommandText="INSERT dbo.AppNotifications(Id,RecipientId,EventKey,Title,Body,Url,At) SELECT NEWID(),u.Id,@Key,@Title,@Body,@Url,@At FROM dbo.AppUsers u WHERE u.Active=1 AND (u.Id=@Recipient OR u.Role=@Role) AND NOT EXISTS(SELECT 1 FROM dbo.AppNotifications n WHERE n.RecipientId=u.Id AND n.EventKey=@Key)";c.Parameters.AddWithValue("@Key",d.EventKey);c.Parameters.AddWithValue("@Title",d.Title);c.Parameters.AddWithValue("@Body",d.Body);c.Parameters.AddWithValue("@Url",d.Url);c.Parameters.AddWithValue("@At",d.At);c.Parameters.Add("@Recipient",System.Data.SqlDbType.UniqueIdentifier).Value=(object?)d.RecipientId??DBNull.Value;c.Parameters.Add("@Role",System.Data.SqlDbType.NVarChar,20).Value=(object?)d.RecipientRole??DBNull.Value;await c.ExecuteNonQueryAsync();}
 }
}
